const b = $input.first().json;
const lines = [`ScoutJobs ${b.date}: ${b.applied_week}/${b.target_week} applied this week, ${b.open} open, streak ${b.streak}d`];
for (const i of b.upcoming_interviews || []) lines.push(`Interview ${i.at} ${i.company} (${i.stage}) prep: ${i.prep_status}`);
for (const j of b.follow_ups_due || []) lines.push(`Follow up: ${j.company} - ${j.title}`);
for (const j of b.drafted_jobs || []) lines.push(`Draft waiting: ${j.company} - ${j.title}`);
if ((b.new_jobs || []).length) lines.push(`${b.new_jobs.length} new postings to score`);
return [{ json: { text: lines.join('\n') } }];
